const EQUATIONS = {
  'AGUIEIRA|chlorophyll_a': {
    name: 'TBDO (Dall\u2019Olmo three-band index)',
    formula: 'TBDO = R740 \u00d7 (1/R665 \u2212 1/R705)',
    model: 'Chl-a (\u00b5g/L) = 7.745 \u00d7 exp(6.2408 \u00d7 TBDO)',
  },
  'AGUIEIRA|secchi_depth': {
    name: 'MCI (Maximum Chlorophyll Index)',
    formula: 'MCI = R560 \u2212 0.4031\u00d7R665 \u2212 0.6359\u00d7R490',
    model: 'Secchi Depth (m) = 4.295 \u00d7 exp(\u221242.467 \u00d7 MCI)',
  },
  'RABAGAO|chlorophyll_a': {
    name: 'TBDO1 (Dall\u2019Olmo three-band index, variant 1)',
    formula: 'TBDO1 = R665 \u00d7 (1/R560 \u2212 1/R443)',
    model: 'Chl-a (\u00b5g/L) = 1.888 \u00d7 exp(\u22121.1323 \u00d7 TBDO1)',
    note: 'Uses the 443nm band \u2014 corrected in v5 after a band-substitution bug (490nm) was found and fixed; see the project history.',
  },
  'RABAGAO|secchi_depth': {
    name: 'NDI (Normalized Difference Index)',
    formula: 'NDI = (R560 \u2212 R665) / (R560 + R665)',
    model: 'Secchi Depth (m) = 5.568 \u2212 3.542 \u00d7 NDI',
  },
};

// Standard OECD-style Chl-a trophic classification bands (µg/L) — used for
// threshold alerts, distinct from Step 8/9's statistical confidence tiers.
const TROPHIC_BANDS = [
  { max: 2.6, key: 'oligo', label: 'Oligotrophic' },
  { max: 8, key: 'meso', label: 'Mesotrophic' },
  { max: 25, key: 'eu', label: 'Eutrophic' },
  { max: Infinity, key: 'hyper', label: 'Hypereutrophic' },
];
function trophicBand(chlaValue) {
  return TROPHIC_BANDS.find(b => chlaValue <= b.max) || TROPHIC_BANDS[TROPHIC_BANDS.length - 1];
}

