const RESERVOIR_ZOOM = { AGUIEIRA: 12, RABAGAO: 12, ALQUEVA: 10 };

const CONFIDENCE_COLORS = { high: '#2e7d32', medium: '#f9a825', low: '#c62828' };

// Fixed export regions — MUST match step10_spatial_maps.js's RESERVOIRS[].bbox
// exactly, since these define how the exported PNGs are georeferenced. This is
