/* ============================== ALERTS ============================== */

/* The export writes each event once per indicator, so identical events repeat. Collapse them. */
function uniqueEvents(list) {
  const seen = new Set(), out = [];
  (list || []).forEach(e => {
    const k = [e.event_type, e.start_date, e.end_date, e.confidence, e.description].join('|');
    if (!seen.has(k)) { seen.add(k); out.push(e); }
  });
  // Same recovery date detected with different decline lengths = one recovery seen twice: keep the strongest (highest speed ratio).
  const ratio = e => parseFloat((String(e.description).match(/speed ratio ([\d.]+)x/) || [0, 0])[1]);
  const best = new Map(), keep = [];
  out.forEach(e => {
    if (e.confidence === 'confirmed') { keep.push(e); return; }
    const k = e.event_type + '|' + e.end_date;
    if (!best.has(k) || ratio(e) > ratio(best.get(k))) best.set(k, e);
  });
  keep.push(...best.values());
  // confirmed first, then newest first
  return keep.sort((a, b) => (b.confidence === 'confirmed') - (a.confidence === 'confirmed') ||
    String(b.end_date || b.start_date).localeCompare(String(a.end_date || a.start_date)));
}

function renderAlerts() {
  const list = document.getElementById('alerts-list');
  list.innerHTML = '';
  const data = state.dashboardData;
  if (!data) { document.getElementById('alert-count').textContent = '0'; return; }
  const resBlock = data.reservoirs[state.reservoir];
  const alerts = [];

  RESERVOIR_INDICATORS[state.reservoir].forEach(ind => {
    const block = resBlock.indicators[ind];
    if (!block) return;
    const meta = INDICATOR_META[ind];
    const recent = block.series.slice(-60).filter(p => p.confidence === 'low');
    recent.forEach(p => {
      alerts.push({
        type: 'anomaly', icon: '⚠', title: meta.label + ' anomaly flagged',
        meta: resBlock.display_name + ' · ' + p.date,
        desc: 'Value ' + meta.fmt(p.value) + ' flagged low-confidence (statistical outlier vs. neighbouring dates).',
      });
    });
  });

  // Threshold alert — CURRENT status only (not every historical day in
  // that band), since Aguieira sits in the eutrophic band most of the
  // time by its own baseline — alerting on that daily would just be
  // restating known context, not flagging something new.
  const chlaBlock = resBlock.indicators['chlorophyll_a'];
  if (chlaBlock) {
    const latest = chlaBlock.latest;
    const band = trophicBand(latest.value);
    if ((band.key === 'eu' || band.key === 'hyper') && latest.confidence !== 'low') {
      alerts.push({
        type: 'threshold', icon: '🌿', title: 'Current status: ' + band.label + ' Chl-a',
        meta: resBlock.display_name + ' · as of ' + latest.date,
        desc: `Latest reading ${latest.value.toFixed(1)} µg/L falls in the ${band.label} range (${band.key === 'hyper' ? '>25' : '8–25'} µg/L).`,
      });
    }
  }

  uniqueEvents(resBlock.events).filter(e => e.confidence !== 'confirmed').forEach(e => {
    alerts.push({
      type: 'event', icon: '◈', title: 'Candidate event: ' + (e.event_type || '').replace(/_/g, ' '),
      meta: resBlock.display_name + ' · ' + (e.end_date || e.start_date || ''),
      desc: e.description || '',
    });
  });

  document.getElementById('alert-count').textContent = alerts.length;
  if (alerts.length === 0) {
    list.innerHTML = '<div style="color:var(--text-muted);font-size:12px;">No recent anomalies or unconfirmed events for this reservoir.</div>';
    return;
  }
  alerts.slice(0, 25).forEach(a => {
    const row = document.createElement('div');
    row.className = 'alert-row' + (a.type === 'event' ? ' event' : '') + (a.type === 'threshold' ? ' threshold' : '');
    row.innerHTML =
      '<div class="alert-icon">' + a.icon + '</div>' +
      '<div class="alert-body"><div class="alert-title">' + a.title + '</div>' +
      '<div class="alert-meta">' + a.meta + '</div>' +
      (a.desc ? '<div class="alert-desc">' + a.desc + '</div>' : '') + '</div>';
    list.appendChild(row);
  });
}

