/* ============================== EVENTS (full section) ============================== */
function findNearestSeriesValue(series, dateStr, direction) {
  // direction: 'before' finds the last point <= dateStr, 'after' finds the first point >= dateStr
  if (!dateStr) return null;
  if (direction === 'before') {
    const candidates = series.filter(p => p.date <= dateStr);
    return candidates.length ? candidates[candidates.length - 1] : null;
  }
  const candidates = series.filter(p => p.date >= dateStr);
  return candidates.length ? candidates[0] : null;
}

function renderEventsFull() {
  const target = document.getElementById('events-full-list');
  target.innerHTML = '';
  const data = state.dashboardData;
  if (!data) { target.innerHTML = '<div style="color:var(--text-muted);">Load data first.</div>'; return; }
  const resBlock = data.reservoirs[state.reservoir];
  document.getElementById('events-reservoir-name').textContent = resBlock.display_name;

  const events = uniqueEvents(resBlock.events);
  if (!events.length) {
    target.innerHTML = '<div style="color:var(--text-muted);font-size:13px;">No events on record for this reservoir.</div>';
    return;
  }
  const volSeries = (resBlock.indicators['volume'] || {}).series;

  events.forEach(e => {
    const isConfirmed = e.confidence === 'confirmed';
    const card = document.createElement('div');
    card.className = 'event-card' + (isConfirmed ? '' : ' unconfirmed');

    let deltaHTML = '';
    if (volSeries && e.start_date && e.end_date) {
      const before = findNearestSeriesValue(volSeries, e.start_date, 'before');
      const after = findNearestSeriesValue(volSeries, e.end_date, 'after') || findNearestSeriesValue(volSeries, e.end_date, 'before');
      if (before && after) {
        const pct = ((after.value - before.value) / before.value * 100);
        const sign = pct >= 0 ? '+' : '';
        const cls = pct >= 0 ? 'diff-pos' : 'diff-neg';
        deltaHTML = `<div class="event-delta">Volume: <b>${before.value.toFixed(1)} hm³</b> (${before.date}) → <b>${after.value.toFixed(1)} hm³</b> (${after.date}) &nbsp; <span class="${cls}">(${sign}${pct.toFixed(0)}%)</span></div>`;
      }
    }

    card.innerHTML =
      '<div class="event-head">' +
      '<span class="event-title">' + (e.event_type || 'event').replace(/_/g, ' ') + '</span>' +
      '<span class="conf-tag ' + e.confidence + '">' + e.confidence + '</span>' +
      '</div>' +
      '<div class="event-dates">' + (e.start_date ? e.start_date + ' → ' + (e.end_date || '?') : 'Recovered by ' + (e.end_date || '?')) + '</div>' +
      '<div class="event-desc">' + (e.description || '') + '</div>' +
      deltaHTML;
    target.appendChild(card);
  });
}

