/* ============================== MODEL VALIDATION (full section) ============================== */
const STAGE_LABELS = {
  full_record_raw: 'Full in-situ record (raw match)',
  full_record_hampel_cleaned: 'Full in-situ record (Hampel-cleaned)',
  paper_model_subset_independent_match: "Paper's own calibration subset (independently re-matched)",
  paper_model_subset_hampel_cleaned: "Paper's own calibration subset (Hampel-cleaned)",
};

function renderValidation() {
  const target = document.getElementById('validation-content');
  target.innerHTML = '';
  if (!state.dashboardData) { target.innerHTML = '<div style="color:var(--text-muted);">Load data first.</div>'; return; }
  document.getElementById('val-reservoir-name').textContent =
    (state.dashboardData && state.dashboardData.reservoirs[state.reservoir]) ?
      state.dashboardData.reservoirs[state.reservoir].display_name : '';

  const indicators = RESERVOIR_INDICATORS[state.reservoir].filter(i => i !== 'surface_area' && i !== 'volume');
  if (indicators.length === 0) {
    target.innerHTML = '<div style="color:var(--text-muted);font-size:13px;">No empirical Chl-a/Secchi Depth model exists for this reservoir (no in-situ calibration data available).</div>';
    return;
  }

  indicators.forEach(ind => {
    const key = state.reservoir + '|' + ind;
    const eq = EQUATIONS[key];
    const meta = INDICATOR_META[ind];
    const block = document.createElement('div');

    let html = '<div class="validation-subhead">' + meta.label + '</div>';
    if (eq) {
      html += '<div class="equation-box">' +
        '<div class="eq-label">' + eq.name + '</div>' + eq.formula + '<br>' +
        '<div class="eq-label" style="margin-top:6px;">Empirical model</div>' + eq.model +
        '</div>';
      if (eq.note) html += '<div class="validation-note">' + eq.note + '</div>';
    }

    // Published (paper) performance
    const perf = state.dashboardData.reservoirs[state.reservoir].indicators[ind].model_performance;
    if (perf) {
      html += '<table class="stats-table"><thead><tr><th colspan="5">Published performance (Lauriuchi et al. 2026, cross-validated)</th></tr>' +
        '<tr><th>R²</th><th>RMSE</th><th>MAE</th><th>MAPE</th><th>Unit</th></tr></thead><tbody>' +
        `<tr><td>${perf.r2}</td><td>${perf.rmse}</td><td>${perf.mae}</td><td>${perf.mape}%</td><td>${perf.unit}</td></tr>` +
        '</tbody></table>';
    }

    // Our own independent validation (Step 8)
    const ourStats = VALIDATION_SUMMARY.filter(r => r.reservoir === state.reservoir &&
      r.indicator === (ind === 'chlorophyll_a' ? 'CHLA' : 'SECCHI'));
    if (ourStats.length) {
      html += '<table class="stats-table"><thead><tr><th colspan="6">This pipeline\u2019s independent validation (Step 8, automated estimates vs. real in-situ readings)</th></tr>' +
        '<tr><th>Dataset</th><th>N</th><th>R²</th><th>RMSE</th><th>MAE</th><th>Bias</th></tr></thead><tbody>';
      ourStats.forEach(r => {
        html += `<tr><td>${STAGE_LABELS[r.stage] || r.stage}</td><td>${r.n}</td><td>${r.r2}</td><td>${r.rmse}</td><td>${r.mae}</td><td>${r.bias}</td></tr>`;
      });
      html += '</tbody></table>';
      html += '<div class="validation-note">R² here is computed directly against the 1:1 line (does the estimate equal the measurement?), a stricter test than a re-fitted regression — expect it to read lower than the published cross-validated R² above even when the equation is working correctly. Negative values mean the estimate is a worse predictor than simply guessing the average.</div>';
    }

    // Real vs predicted sample table
    const matched = MATCHED_PAIRS[key];
    if (matched && matched.length) {
      html += '<div class="validation-subhead">Real (in-situ) vs. predicted (satellite) — full matched record, n=' + matched.length + '</div>';
      html += '<div style="max-height:260px;overflow-y:auto;"><table class="validation-table"><thead><tr>' +
        '<th>Sampling date</th><th>In-situ</th><th>Satellite est.</th><th>Difference</th><th>Match gap (days)</th>' +
        '</tr></thead><tbody>';
      matched.forEach(r => {
        const diff = r.satellite - r.insitu;
        const cls = Math.abs(diff) > (ind === 'chlorophyll_a' ? 5 : 1) ? (diff > 0 ? 'diff-pos' : 'diff-neg') : '';
        html += `<tr><td>${r.date}</td><td>${r.insitu} ${meta.unit}</td><td>${r.satellite} ${meta.unit}</td>` +
          `<td class="${cls}">${diff >= 0 ? '+' : ''}${diff.toFixed(2)}</td><td>${r.gap_days}</td></tr>`;
      });
      html += '</tbody></table></div>';
    }

    block.innerHTML = html;
    target.appendChild(block);
  });
}

/* ============================== DATE SLIDER ============================== */
function dateRangeForReservoir() {
  const data = state.dashboardData;
  if (!data) return null;
  const resBlock = data.reservoirs[state.reservoir];
  const anyInd = RESERVOIR_INDICATORS[state.reservoir].find(i => resBlock.indicators[i]);
  const series = resBlock.indicators[anyInd].series;
  return { min: series[0].date, max: series[series.length - 1].date };
}

function setupDateSlider() {
  const range = dateRangeForReservoir();
  const slider = document.getElementById('date-slider');
  if (!range) { slider.disabled = true; return; }
  slider.disabled = false;
  slider.min = 0;
  const days = Math.round((new Date(range.max) - new Date(range.min)) / 86400000);
  slider.max = days;
  slider.value = days;
  state.selectedDate = range.max;
  state._rangeMin = range.min;
  updateDateLabel();
}

function updateDateLabel() {
  document.getElementById('date-label').textContent = state.selectedDate || '—';
}

document.getElementById('date-slider').addEventListener('input', (e) => {
  const days = parseInt(e.target.value, 10);
  const d = new Date(state._rangeMin);
  d.setDate(d.getDate() + days);
  state.selectedDate = d.toISOString().slice(0, 10);
  updateDateLabel();
  renderImageOverlay();
});

document.getElementById('play-btn').addEventListener('click', () => {
  state.playing = !state.playing;
  document.getElementById('play-btn').textContent = state.playing ? '⏸' : '▶';
  if (state.playing) {
    state.playTimer = setInterval(() => {
      const slider = document.getElementById('date-slider');
      let v = parseInt(slider.value, 10) + Math.max(1, Math.round(slider.max / 100));
      if (v > slider.max) v = 0;
      slider.value = v;
      slider.dispatchEvent(new Event('input'));
    }, 400);
  } else {
    clearInterval(state.playTimer);
  }
});

/* ============================== DATA LOADING ============================== */
function registerSpatialImage(name, url) {
  // expected filename: RESERVOIR_INDICATOR_YYYY-MM-DD.png, e.g. AGUIEIRA_CHLA_2024-05-31.png
  const m = name.match(/^([A-Z]+)_(CHLA|SD)_(\d{4}-\d{2}-\d{2})\.png$/i);
  if (!m) return false;
  const indicator = m[2].toUpperCase() === 'CHLA' ? 'chlorophyll_a' : 'secchi_depth';
  const listKey = m[1].toUpperCase() + '|' + indicator;
  state.spatialImages[listKey + '|' + m[3]] = url;
  if (!state.spatialDatesByKey[listKey]) state.spatialDatesByKey[listKey] = [];
  if (!state.spatialDatesByKey[listKey].includes(m[3])) state.spatialDatesByKey[listKey].push(m[3]);
  return true;
}
function sortSpatialDates() { Object.values(state.spatialDatesByKey).forEach(a => a.sort()); }

