function openInfoModal(ind) {
  const key = state.reservoir + '|' + ind;
  const eq = EQUATIONS[key];
  const meta = INDICATOR_META[ind];
  const data = state.dashboardData;
  if (!data) return;
  const resBlock = data.reservoirs[state.reservoir];
  const indBlock = resBlock.indicators[ind];
  const perf = indBlock ? indBlock.model_performance : null;
  const matched = MATCHED_PAIRS[key] || [];

  let html = '<h3>' + meta.label + ' — ' + resBlock.display_name + '</h3>';
  html += '<div class="section-sub" style="margin-bottom:10px;">How this indicator is estimated from Sentinel-2, and how well it matches real field readings.</div>';

  if (eq) {
    html += '<div class="equation-box">' +
      '<div class="eq-label">' + eq.name + '</div>' + eq.formula + '<br>' +
      '<div class="eq-label" style="margin-top:6px;">Empirical model</div>' + eq.model +
      '</div>';
    if (eq.note) html += '<div class="validation-note">' + eq.note + '</div>';
  } else {
    html += '<div class="section-sub">This indicator is computed directly (surface-area / bathymetric volume), not via a calibrated empirical reflectance model — so there is no equation or independent validation to show.</div>';
  }

  if (perf) {
    html += '<table class="stats-table"><thead><tr><th colspan="5">Published performance (Lauriuchi et al. 2026, cross-validated)</th></tr>' +
      '<tr><th>R²</th><th>RMSE</th><th>MAE</th><th>MAPE</th><th>Unit</th></tr></thead><tbody>' +
      `<tr><td>${perf.r2}</td><td>${perf.rmse}</td><td>${perf.mae}</td><td>${perf.mape}%</td><td>${perf.unit}</td></tr>` +
      '</tbody></table>';
  }

  if (matched.length) {
    html += '<div class="validation-subhead">In-situ vs. satellite — n=' + matched.length + ' matched samples</div>';
    html += '<div id="info-modal-canvas-wrap"><canvas id="info-modal-canvas"></canvas></div>';
  }

  document.getElementById('info-modal-body').innerHTML = html;
  document.getElementById('info-modal-backdrop').classList.remove('hidden');

  if (matched.length) {
    const ctx = document.getElementById('info-modal-canvas').getContext('2d');
    const vals = matched.flatMap(r => [r.insitu, r.satellite]);
    const lo = Math.min(...vals), hi = Math.max(...vals);
    if (infoModalChart) infoModalChart.destroy();
    infoModalChart = new Chart(ctx, {
      type: 'scatter',
      data: {
        datasets: [
          {
            label: '1:1 line', type: 'line',
            data: [{ x: lo, y: lo }, { x: hi, y: hi }],
            borderColor: 'rgba(20,35,31,0.35)', borderDash: [4, 4], borderWidth: 1.5,
            pointRadius: 0, fill: false,
          },
          {
            label: 'Matched samples',
            data: matched.map(r => ({ x: r.insitu, y: r.satellite })),
            backgroundColor: 'rgba(15,158,147,0.75)',
            pointRadius: 4, pointHoverRadius: 6,
          },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false, animation: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { title: { display: true, text: 'In-situ (' + meta.unit + ')', font: { size: 10 } }, ticks: { font: { size: 10 } } },
          y: { title: { display: true, text: 'Satellite est. (' + meta.unit + ')', font: { size: 10 } }, ticks: { font: { size: 10 } } },
        }
      }
    });
  }
}


/* ============================== HIGH-CONTRAST SERIES CHART (shared by card + modal) ============================== */
const CHART_PT = { high: '#1b5e20', medium: '#ef6c00', low: '#d50000' };
function buildSeriesChart(ctx, series, meta, ind, big) {
  const step = Math.max(1, Math.floor(series.length / (big ? 1500 : 800)));
  const s = series.filter((_, i) => i % step === 0 || i === series.length - 1 || series[i].confidence === 'low');
  const sz = big ? 1.4 : 1;
  // dashed threshold lines (Chl-a trophic bands): amber = eutrophic, red = hypereutrophic
  const thresholds = { id: 'thresholds', afterDatasetsDraw(c) {
    if (ind !== 'chlorophyll_a') return;
    const { ctx: g, chartArea: a, scales: { y } } = c;
    [[8, '#ef6c00', 'Eutrophic 8'], [25, '#d50000', 'Hypereutrophic 25']].forEach(([v, col, lab]) => {
      if (v < y.min || v > y.max) return;
      const py = y.getPixelForValue(v);
      g.save(); g.strokeStyle = col; g.lineWidth = 1.5; g.setLineDash([6, 4]);
      g.beginPath(); g.moveTo(a.left, py); g.lineTo(a.right, py); g.stroke();
      g.setLineDash([]); g.fillStyle = col; g.font = '600 ' + (big ? 12 : 10) + 'px Inter, sans-serif';
      g.fillText(lab + ' µg/L', a.left + 6, py - 4); g.restore();
    });
  } };
  return new Chart(ctx, {
    type: 'line',
    plugins: [thresholds],
    data: {
      labels: s.map(p => p.date),
      datasets: [{
        data: s.map(p => p.value),
        borderColor: '#1a2b3c', borderWidth: big ? 2 : 1.6,
        pointRadius: s.map(p => (p.confidence === 'low' ? 5 : p.confidence === 'medium' ? 3.5 : 2.2) * sz),
        pointBackgroundColor: s.map(p => CHART_PT[p.confidence] || '#455a64'),
        pointBorderColor: '#fff', pointBorderWidth: 0.8,
        fill: false, tension: 0.12,
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      interaction: { mode: 'nearest', intersect: false },
      plugins: { legend: { display: false } },
      scales: {
        x: { ticks: { maxTicksLimit: big ? 16 : 8, font: { size: big ? 12 : 10 }, color: '#1a2b3c' }, grid: { color: 'rgba(20,35,31,0.08)' } },
        y: { title: { display: true, text: meta.unit, color: '#1a2b3c', font: { size: big ? 12 : 10 } },
             ticks: { font: { size: big ? 12 : 10 }, color: '#1a2b3c' }, grid: { color: 'rgba(20,35,31,0.14)' } },
      }
    }
  });
}


/* Suspected artifact = low-confidence point that is >4x (or <1/4 of) the median of its 3 neighbours on each side.
   Applied to Chl-a and Secchi only. Points are flagged, never deleted. */
state.hideArtifacts = true;
function flagSuspectedArtifacts(data) {
  Object.values(data.reservoirs).forEach(r => ['chlorophyll_a', 'secchi_depth'].forEach(ind => {
    const b = r.indicators[ind]; if (!b) return;
    const s = b.series;
    s.forEach((p, i) => {
      p.suspect = false;
      if (p.confidence !== 'low') return;
      const nb = s.slice(Math.max(0, i - 3), i).concat(s.slice(i + 1, i + 4)).map(q => q.value).sort((a, c) => a - c);
      if (nb.length < 3) return;
      const med = nb[Math.floor(nb.length / 2)];
      if (med > 0 && (p.value > 4 * med || p.value < med / 4)) p.suspect = true;
    });
  }));
}
function visibleSeries(block) { return state.hideArtifacts ? block.series.filter(p => !p.suspect) : block.series; }
function updateArtifactUI(ind) {
  const data = state.dashboardData; if (!data) return;
  const r = data.reservoirs[state.reservoir];
  const n = ['chlorophyll_a', 'secchi_depth'].reduce((a, k) => a + (r.indicators[k] ? r.indicators[k].series.filter(p => p.suspect).length : 0), 0);
  document.querySelectorAll('.artifact-count').forEach(el => el.textContent = '(' + n + ' in ' + r.display_name + ')');
  document.querySelectorAll('.hide-artifacts-cb').forEach(cb => cb.checked = state.hideArtifacts);
}
document.querySelectorAll('.hide-artifacts-cb').forEach(cb => cb.addEventListener('change', e => {
  state.hideArtifacts = e.target.checked;
  updateArtifactUI();
  renderCharts(); renderBigCharts();
  if (chartModalInstance && chartModalInd) openChartModal(chartModalInd);
}));

let chartModalInstance = null, chartModalInd = null;
function openChartModal(ind) {
  chartModalInd = ind;
  const block = state.dashboardData.reservoirs[state.reservoir].indicators[ind];
  const meta = INDICATOR_META[ind];
  document.getElementById('chart-modal-title').textContent =
    state.dashboardData.reservoirs[state.reservoir].display_name + ' — ' + meta.label + ' (' + meta.unit + ')';
  document.getElementById('chart-modal-backdrop').classList.remove('hidden');
  if (chartModalInstance) chartModalInstance.destroy();
  chartModalInstance = buildSeriesChart(document.querySelector('#chart-modal-canvas-wrap canvas').getContext('2d'), visibleSeries(block), meta, ind, true);
}
function closeChartModal() {
  document.getElementById('chart-modal-backdrop').classList.add('hidden');
  if (chartModalInstance) { chartModalInstance.destroy(); chartModalInstance = null; }
  chartModalInd = null;
}
document.getElementById('chart-modal-close').addEventListener('click', closeChartModal);
document.getElementById('chart-modal-backdrop').addEventListener('click', e => { if (e.target.id === 'chart-modal-backdrop') closeChartModal(); });

/* ============================== MAP SIZE ROBUSTNESS ============================== */
// Leaflet caches the container's pixel size at init; if the layout shifts
// afterward (fonts loading, panel content changing height, window resize)
// tiles/overlays can appear frozen until the map is told to re-measure.
window.addEventListener('resize', () => map.invalidateSize());
if (typeof ResizeObserver !== 'undefined') {
  new ResizeObserver(() => map.invalidateSize()).observe(document.getElementById('map'));
}
setTimeout(() => map.invalidateSize(), 300);


/* initial paint: boundary-only view before any data is loaded */
refreshMap(true);
renderSitesTable();

async function autoLoad() {
  const status = document.getElementById('file-status');
  status.textContent = 'Loading…';
  try {
    const res = await fetch('data/dashboard_data.json');
    if (!res.ok) throw new Error('HTTP ' + res.status);
    state.dashboardData = await res.json();
    // The export repeats every row (3-4x per date); keep one point per date so charts/trends aren't inflated.
    Object.values(state.dashboardData.reservoirs).forEach(r => Object.values(r.indicators).forEach(b => {
      const seen = new Set();
      b.series = b.series.filter(p => !seen.has(p.date) && seen.add(p.date));
    }));
    flagSuspectedArtifacts(state.dashboardData);
    status.textContent = 'Data updated ' + new Date(state.dashboardData.generated_at).toLocaleDateString();
    document.getElementById('empty-state').classList.add('hidden');
    setupDateSlider();
    renderAll(true);
    switchTab('overview');
  } catch (err) {
    console.error('Auto-load of data/dashboard_data.json failed:', err);
    status.textContent = '';
    return; // empty state stays visible
  }
  try {
    const res = await fetch('data/spatial_manifest.json');
    if (!res.ok) throw new Error('HTTP ' + res.status);
    (await res.json()).forEach(n => registerSpatialImage(n, 'data/spatial_maps_png/' + n));
    sortSpatialDates();
    renderImageOverlay();
  } catch (err) {
    console.warn('Spatial manifest not loaded:', err);
  }
}
autoLoad();

/* ============================== EXPAND / COLLAPSE PANEL ============================== */
const sidePanel = document.getElementById('side-panel');
function setExpanded(on) {
  sidePanel.classList.toggle('expanded', on);
  document.body.classList.toggle('panel-expanded', on);
  document.querySelectorAll('.tab-panel > .col-head > .expand-btn').forEach(b => {
    b.textContent = on ? '⤡ Collapse' : '⤢ Expand';
    b.setAttribute('aria-expanded', String(on));
  });
  setTimeout(() => { Object.values(bigChartInstances).forEach(c => c.resize()); map.invalidateSize(); }, 260);
}
document.querySelectorAll('.tab-panel > .col-head').forEach(head => {
  const btn = document.createElement('button');
  btn.className = 'expand-btn'; btn.type = 'button'; btn.textContent = '⤢ Expand';
  btn.setAttribute('aria-expanded', 'false');
  btn.addEventListener('click', () => setExpanded(!sidePanel.classList.contains('expanded')));
  head.appendChild(btn);
});
document.addEventListener('keydown', e => { if (e.key === 'Escape' && !document.getElementById('chart-modal-backdrop').classList.contains('hidden')) { closeChartModal(); return; } if (e.key === 'Escape' && sidePanel.classList.contains('expanded')) setExpanded(false); });
